package main

import (
	"encoding/json"
	"fmt"
)

type User struct {
	ID        int      `json:"id"`
	Name      string   `json:"name"`
	Email     string   `json:"email,omitempty"` // dropped if empty
	Nickname  *string  `json:"nickname,omitempty"` // pointer: nil => absent
	Password  string   `json:"-"`               // never marshaled
	internal  string   // unexported: always ignored
}

func main() {
	u := User{ID: 7, Name: "Ada", Password: "secret", internal: "x"}

	b, _ := json.Marshal(u)
	fmt.Println(string(b))

	pretty, _ := json.MarshalIndent(u, "", "  ")
	fmt.Println(string(pretty))

	var back User
	_ = json.Unmarshal([]byte(`{"id":9,"name":"Lin","nickname":"L"}`), &back)
	fmt.Printf("%d %s nickname=%s\n", back.ID, back.Name, *back.Nickname)
}

package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

type Date struct{ time.Time }

const layout = "2006-01-02"

func (d Date) MarshalJSON() ([]byte, error) {
	return []byte(`"` + d.Format(layout) + `"`), nil
}

func (d *Date) UnmarshalJSON(b []byte) error {
	s := strings.Trim(string(b), `"`)
	t, err := time.Parse(layout, s)
	if err != nil {
		return err
	}
	d.Time = t
	return nil
}

type Event struct {
	Name string `json:"name"`
	Day  Date   `json:"day"`
}

func main() {
	e := Event{Name: "launch", Day: Date{time.Date(2026, 6, 24, 0, 0, 0, 0, time.UTC)}}
	b, _ := json.Marshal(e)
	fmt.Println(string(b))

	var back Event
	_ = json.Unmarshal([]byte(`{"name":"demo","day":"2026-12-31"}`), &back)
	fmt.Println(back.Name, back.Day.Format(layout))

	var any map[string]any
	_ = json.Unmarshal([]byte(`{"id":10000000000000001}`), &any)
	fmt.Printf("%T %v\n", any["id"], any["id"])
}
